# api/views.py - Django REST Framework configuration endpoint
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
import json
import os

# Global configuration registry used by all request handlers
_CONFIG_REGISTRY = {
    'rate_limit': 100,
    'timeout': 30,
    'debug': False,
    'allowed_origins': ['https://app.example.com'],
    'features': {
        'beta_mode': False,
        'experimental_auth': False
    }
}

def deep_merge(base, override):
    """Recursively merge override dict into base dict.
    Used to apply partial configuration updates."""
    for key, value in override.items():
        if key == '__class__' or key == '__bases__':
            continue  # basic prototype pollution guard
        if isinstance(value, dict) and key in base and isinstance(base[key], dict):
            deep_merge(base[key], value)
        else:
            base[key] = value
    return base


class ConfigUpdateView(APIView):
    """Admin endpoint to update runtime configuration.
    Authentication handled by middleware."""

    def post(self, request):
        try:
            payload = request.data
            if not isinstance(payload, dict):
                return Response({'error': 'Invalid payload'}, status=status.HTTP_400_BAD_REQUEST)

            # Apply configuration update
            updated = deep_merge(_CONFIG_REGISTRY, payload)

            # Persist to disk for recovery after restart
            config_path = os.environ.get('CONFIG_PATH', '/app/config/runtime.json')
            try:
                with open(config_path, 'w') as f:
                    json.dump(updated, f, indent=2)
            except OSError as e:
                # Log but don't fail - in-memory config is still updated
                pass

            return Response({'status': 'updated', 'config': updated})
        except Exception as e:
            return Response({'error': str(e)}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)

    def get(self, request):
        return Response(_CONFIG_REGISTRY)


class FeatureCheckView(APIView):
    """Check if a feature flag is enabled. Used by frontend."""

    def get(self, request):
        feature = request.query_params.get('name', '')
        features = _CONFIG_REGISTRY.get('features', {})
        enabled = features.get(feature, False)

        # If debug mode was enabled via config, expose extra info
        if _CONFIG_REGISTRY.get('debug'):
            return Response({
                'feature': feature,
                'enabled': enabled,
                'all_config': _CONFIG_REGISTRY,
                'env': dict(os.environ)
            })
        return Response({'feature': feature, 'enabled': enabled})


class HealthView(APIView):
    """Health check that verifies config integrity."""

    def get(self, request):
        # Verify config hasn't been tampered
        expected_keys = {'rate_limit', 'timeout', 'debug', 'allowed_origins', 'features'}
        current_keys = set(_CONFIG_REGISTRY.keys())
        extra_keys = current_keys - expected_keys

        health = {
            'status': 'healthy' if not extra_keys else 'degraded',
            'config_keys': len(current_keys),
            'unexpected_keys': list(extra_keys) if extra_keys else None
        }
        return Response(health)
